// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    function setUp() public { c = new airPort(); }

    // fuzz parameters: from address, one recipient address, value, and a boolean to choose failure mode of callee
    function testFuzz_property(address from, address recipient, uint256 v, bool shouldRevert) public {
        // keep inputs admissible
        vm.assume(from != address(0));
        vm.assume(recipient != address(0));
        // build a single-element _tos array to make per-call observations simple
        address[] memory tos = new address[](1);
        tos[0] = recipient;

        // deploy a recorder that exposes exactly the transferFrom signature and records the last call
        Recorder rec = new Recorder();
        // configure recorder to either revert or succeed based on fuzzed boolean
        rec.setShouldRevert(shouldRevert);

        // We'll route c's calls to the recorder address so that recorder's transferFrom is invoked
        // Call and observe whether c completes and what the recorder recorded.
        bool ok;
        try c.transfer(from, address(rec), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // The GENERAL RULE (reference C satisfies for ALL inputs):
        // If the callee implements transferFrom and either always reverts or always succeeds,
        // then c.transfer's behavior corresponds to calling transferFrom(from, tos[0], v) (i.e., the recorder's recorded selector and decoded args match transferFrom),
        // so when the recorder is set to NOT revert, c.transfer must succeed and recorder must have recorded a call with selector == keccak256("transferFrom(address,address,uint256)").
        // The mutant that changed the selector to transfer(...) will cause the recorder.transferFrom NOT to be invoked with that selector/args for some inputs.

        // We assert the property for the case where the callee does NOT revert: the reference must succeed and the recorder must have recorded the transferFrom call with matching decoded args.
        if (!shouldRevert) {
            // For the correct contract, the call must not revert and the recorder must have recorded the exact arguments
            // Read the recorder's recorded fields (this observes c only through external behavior it caused)
            bytes4 recordedSelector = rec.lastSelector();
            address recordedFrom = rec.lastFrom();
            address recordedTo = rec.lastTo();
            uint256 recordedV = rec.lastV();

            // The single assertion reads c's observable behavior via the recorder getters and the try/catch result.
            // It requires that the call succeeded (ok == true) AND the recorder saw the transferFrom selector and the exact arguments.
            assertTrue(
                ok
                && recordedSelector == bytes4(keccak256("transferFrom(address,address,uint256)"))
                && recordedFrom == from
                && recordedTo == recipient
                && recordedV == v
            );
        } else {
            // If the callee reverts, the reference contract will revert as it requires the call to succeed (require(_s));
            // so ok must be false for the reference. We assert that behavior here to keep the test universally valid on the reference.
            assertTrue(!ok);
        }
    }
}

// Recorder that implements transferFrom(address,address,uint256) and records the last call.
contract Recorder {
    bool public shouldRevert;
    bytes4 private _lastSelector;
    address private _lastFrom;
    address private _lastTo;
    uint256 private _lastV;

    function setShouldRevert(bool r) external { shouldRevert = r; }

    // This function matches the selector used by the correct contract.
    function transferFrom(address from, address to, uint256 v) external returns (bool) {
        _lastSelector = msg.sig;
        _lastFrom = from;
        _lastTo = to;
        _lastV = v;
        if (shouldRevert) revert("rec revert");
        return true;
    }

    // getters for the test to observe what was recorded
    function lastSelector() external view returns (bytes4) { return _lastSelector; }
    function lastFrom() external view returns (address) { return _lastFrom; }
    function lastTo() external view returns (address) { return _lastTo; }
    function lastV() external view returns (uint256) { return _lastV; }
}
